package com.restaurant.management.service;
import com.restaurant.management.dto.*; import com.restaurant.management.entity.JournalActivite; import com.restaurant.management.enums.ResultatActivite; import com.restaurant.management.repository.JournalActiviteRepository; import jakarta.persistence.criteria.Predicate; import org.springframework.data.domain.Page; import org.springframework.data.jpa.domain.Specification; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDate; import java.util.*;
@Service
public class ConsultationJournalService {
 private static final Map<String,String> TRI=Map.of("creeLe","creeLe","action","action","typeRessource","typeRessource","resultat","resultat"); private final JournalActiviteRepository repository; public ConsultationJournalService(JournalActiviteRepository r){repository=r;}
 @Transactional(readOnly=true) @PreAuthorize("hasAuthority('JOURNAL_ACTIVITE_CONSULTER')")
 public PageResponse<JournalActiviteResponse> rechercher(LocalDate debut,LocalDate fin,String action,String typeRessource,ResultatActivite resultat,Long utilisateurId,int page,int taille,String tri,String direction){PeriodeTableauBord p=PeriodeTableauBord.creer(debut,fin);String a=normaliser(action),t=normaliser(typeRessource);Specification<JournalActivite> spec=(root,q,cb)->{List<Predicate> ps=new ArrayList<>();ps.add(cb.greaterThanOrEqualTo(root.get("creeLe"),p.debutInstant()));ps.add(cb.lessThan(root.get("creeLe"),p.finExclusive()));if(a!=null)ps.add(cb.equal(root.get("action"),a));if(t!=null)ps.add(cb.equal(root.get("typeRessource"),t));if(resultat!=null)ps.add(cb.equal(root.get("resultat"),resultat));if(utilisateurId!=null)ps.add(cb.equal(root.get("utilisateur").get("id"),utilisateurId));return cb.and(ps.toArray(Predicate[]::new));};Page<JournalActiviteResponse> result=repository.findAll(spec,RechercheServiceSupport.pageable(page,taille,tri,direction,TRI)).map(this::dto);return PageResponse.depuis(result);}
 @Transactional(readOnly=true) @PreAuthorize("hasAuthority('JOURNAL_ACTIVITE_CONSULTER')")
 public List<UtilisateurJournalResponse> listerUtilisateurs(){return repository.findUtilisateursDuJournal();}
 private JournalActiviteResponse dto(JournalActivite j){var u=j.getUtilisateur();var e=u==null?null:u.getEmploye();return new JournalActiviteResponse(j.getId(),u==null?null:u.getId(),e==null?null:e.getPrenom()+" "+e.getNom(),j.getAction(),j.getTypeRessource(),j.getRessourceId(),j.getResultat(),j.getCorrelationId(),j.getCreeLe());}
 private String normaliser(String v){return v==null||v.isBlank()?null:v.strip();}
}
